const sqlPathSnapshotFiles={"query_paths.py": "\"\"\"Actual SQLite plans and progress callbacks for one fixed order-list query.\n\nFour independent in-memory databases contain the same 240 rows. Progress\ncallbacks with N=1 are an observation, not exact row/IO counts or a timer.\n\"\"\"\nimport json\nfrom contextlib import closing\nimport platform\nimport sqlite3\n\nROWS = [(i, (i-1) % 3, \"paid\" if i % 4 == 0 else \"pending\",\n         1000+i, i*7, \"note-\"+str(i)) for i in range(1, 241)]\nQUERY = \"\"\"SELECT id, amount FROM orders\nWHERE tenant=? AND status=? AND created>=?\nORDER BY created DESC, id DESC LIMIT 5\"\"\"\nPARAMS = (1, \"paid\", 1100)\nINDEXES = {\n    \"no_index\": None,\n    \"tenant_only\": \"CREATE INDEX feed_tenant ON orders(tenant)\",\n    \"composite\": \"CREATE INDEX feed_order ON orders(tenant,status,created DESC,id DESC)\",\n    \"covering\": \"CREATE INDEX feed_cover ON orders(tenant,status,created DESC,id DESC,amount)\",\n}\n\n\ndef inspect(connection, query):\n    plan = [list(row) for row in connection.execute(\"EXPLAIN QUERY PLAN \"+query, PARAMS)]\n    # Prepare and execute once before counting; statement caching is left enabled.\n    warmed = connection.execute(query, PARAMS).fetchall()\n    callbacks = 0\n\n    def progress():\n        nonlocal callbacks\n        callbacks += 1\n        return 0\n\n    connection.set_progress_handler(progress, 1)\n    try:\n        rows = connection.execute(query, PARAMS).fetchall()\n    finally:\n        connection.set_progress_handler(None, 0)\n    assert rows == warmed and callbacks > 0\n    return {\"plan\": plan, \"result\": rows, \"progress_callbacks_n1\": callbacks}\n\n\ndef main():\n    expected = [(236, 1652), (224, 1568), (212, 1484), (200, 1400), (188, 1316)]\n    cases = {}\n    expression_sort = None\n    for name, ddl in INDEXES.items():\n        with closing(sqlite3.connect(\":memory:\")) as db:\n            db.execute(\"CREATE TABLE orders(id INTEGER PRIMARY KEY, tenant INT, \"\n                       \"status TEXT, created INT, amount INT, note TEXT)\")\n            db.executemany(\"INSERT INTO orders VALUES(?,?,?,?,?,?)\", ROWS)\n            if ddl:\n                db.execute(ddl)\n            db.commit()\n            cases[name] = {\"index_ddl\": ddl, **inspect(db, QUERY)}\n            assert cases[name][\"result\"] == expected\n            if name == \"covering\":\n                changed = QUERY.replace(\"created DESC, id DESC\", \"abs(created) DESC, id DESC\")\n                expression_sort = {\"query\": changed, **inspect(db, changed)}\n                assert expression_sort[\"result\"] == expected\n    counts = {\"all_rows\": len(ROWS),\n              \"tenant_rows\": sum(r[1] == 1 for r in ROWS),\n              \"tenant_status_rows\": sum(r[1] == 1 and r[2] == \"paid\" for r in ROWS),\n              \"all_predicates_rows\": sum(r[1] == 1 and r[2] == \"paid\" and r[3] >= 1100\n                                         for r in ROWS), \"returned_rows\": 5}\n    assert counts == {\"all_rows\":240, \"tenant_rows\":80, \"tenant_status_rows\":20,\n                      \"all_predicates_rows\":12, \"returned_rows\":5}\n    print(json.dumps({\"status\":\"passed\", \"python\":platform.python_version(),\n                      \"sqlite\":sqlite3.sqlite_version, \"query\":QUERY, \"parameters\":PARAMS,\n                      \"distribution_counts\":counts, \"cases\":cases,\n                      \"expression_sort\":expression_sort,\n                      \"metric_scope\":(\n                          \"Progress callbacks at N=1 after warming the statement; \"\n                          \"not exact VM instructions, visited rows, physical IO or elapsed time. \"\n                          \"EXPLAIN text is diagnostic and may change by SQLite version.\")}, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "snapshot_retry.py": "\"\"\"Two independent SQLite/WAL connections, interleaved in one local process.\n\nBoth cases restock 10 and intend to remove 5 from initial stock 100.\nReusing the old computed absolute value after rollback loses the restock.\n\"\"\"\nimport json\nfrom pathlib import Path\nimport platform\nimport sqlite3\nfrom tempfile import TemporaryDirectory\n\n\ndef scenario(path, reuse_stale_value):\n    reader = sqlite3.connect(path, isolation_level=None, timeout=0)\n    writer = sqlite3.connect(path, isolation_level=None, timeout=0)\n    events = []\n    try:\n        assert reader.execute(\"PRAGMA journal_mode=WAL\").fetchone()[0] == \"wal\"\n        reader.execute(\"CREATE TABLE stock(id INTEGER PRIMARY KEY, units INT NOT NULL)\")\n        reader.execute(\"INSERT INTO stock VALUES(1,100)\")\n        reader.execute(\"BEGIN\")\n        old = reader.execute(\"SELECT units FROM stock WHERE id=1\").fetchone()[0]\n        events.append({\"step\":1, \"connection\":\"R\", \"event\":\"read_snapshot\", \"units\":old})\n        writer.execute(\"BEGIN IMMEDIATE\")\n        writer.execute(\"UPDATE stock SET units=units+10 WHERE id=1\")\n        writer.execute(\"COMMIT\")\n        current = writer.execute(\"SELECT units FROM stock WHERE id=1\").fetchone()[0]\n        events.append({\"step\":2, \"connection\":\"W\", \"event\":\"restock_committed\", \"units\":current})\n        still_old = reader.execute(\"SELECT units FROM stock WHERE id=1\").fetchone()[0]\n        events.append({\"step\":3, \"connection\":\"R\", \"event\":\"same_snapshot\", \"units\":still_old})\n        assert old == still_old == 100 and current == 110\n        try:\n            reader.execute(\"UPDATE stock SET units=units-5 WHERE id=1 AND units>=5\")\n        except sqlite3.OperationalError as error:\n            rejected = {\n                \"message\":str(error),\n                \"sqlite_errorcode\":getattr(error,\"sqlite_errorcode\",None),\n                \"sqlite_errorname\":getattr(error,\"sqlite_errorname\",None)}\n            assert \"locked\" in str(error).lower()\n            assert rejected[\"sqlite_errorcode\"] in (None,517)\n        else:\n            raise AssertionError(\"stale WAL read transaction unexpectedly became a writer\")\n        events.append({\"step\":4, \"connection\":\"R\", \"event\":\"write_upgrade_rejected\", **rejected})\n        assert reader.in_transaction\n        reader.execute(\"ROLLBACK\")\n        events.append({\"step\":5, \"connection\":\"R\", \"event\":\"rollback_old_snapshot\"})\n        reader.execute(\"BEGIN IMMEDIATE\")\n        if reuse_stale_value:\n            reader.execute(\"UPDATE stock SET units=? WHERE id=1\", (old-5,))\n            events.append({\"step\":6, \"connection\":\"R\",\n                           \"event\":\"reuse_old_absolute_value\", \"units\":old-5})\n        else:\n            fresh = reader.execute(\"SELECT units FROM stock WHERE id=1\").fetchone()[0]\n            assert fresh == 110\n            changed = reader.execute(\n                \"UPDATE stock SET units=units-5 WHERE id=1 AND units>=5\").rowcount\n            assert changed == 1\n            events.append({\"step\":6, \"connection\":\"R\", \"event\":\"revalidate_and_remove\",\n                           \"fresh_units\":fresh, \"removed\":5})\n        reader.execute(\"COMMIT\")\n        final = writer.execute(\"SELECT units FROM stock WHERE id=1\").fetchone()[0]\n        expected = 100+10-5\n        events.append({\"step\":7, \"connection\":\"W\", \"event\":\"observe_final_commit\", \"units\":final})\n        assert final == (95 if reuse_stale_value else expected)\n        return {\"events\":events, \"final_units\":final, \"business_expected_units\":expected,\n                \"conserves_business_changes\":final==expected}\n    finally:\n        reader.close()\n        writer.close()\n\n\ndef main():\n    with TemporaryDirectory(prefix=\"infra-snapshot-\") as directory:\n        root=Path(directory)\n        correct=scenario(root/\"fresh.db\", False)\n        wrong=scenario(root/\"stale.db\", True)\n    print(json.dumps({\"status\":\"passed\", \"python\":platform.python_version(),\n                      \"sqlite\":sqlite3.sqlite_version, \"revalidate\":correct,\n                      \"reuse_stale_absolute_value\":wrong,\n                      \"scope\":(\n                          \"Actual local WAL transactions on two separate connections \"\n                          \"interleaved in one process; no threads, external service, \"\n                          \"InnoDB or cloud database tested.\")}, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n"};
